    if "TED ENVIADA PONTE CAMBIO" in desc:
        return _res(
            rules.CONTA_RECURSO_LOJISTA_REMESSA,
            motivo=(
                "TED à Ponte Câmbio para liquidação de operações "
                "(contrapartida de recursos de lojista)."
            ),
        )
